def resolve_duplicate_team_ids(apps, schema_editor):
    """
    Resolve duplicate active SlackIntegration team_id entries.

    Policy:
    - For each duplicate active team_id:
      1. Keep the most recently updated active integration
      2. Deactivate the other active duplicates
    """
    import logging

    logger = logging.getLogger(__name__)

    SlackIntegration = apps.get_model('shared', 'SlackIntegration')

    from django.db.models import Count

    duplicates = (
        SlackIntegration.objects.filter(is_active=True)
        .values('team_id')
        .annotate(count=Count('id')) \
        .filter(count__gt=1)
    )

    if not duplicates:
        logger.info("No duplicate active Slack team_id entries found")
        return

    logger.warning(
        f"Found {len(duplicates)} duplicate active Slack team_id entries, resolving automatically"
    )

    for duplicate in duplicates:
        team_id = duplicate['team_id']
        count = duplicate['count']

        integrations = list(
            SlackIntegration.objects.filter(team_id=team_id, is_active=True).order_by('-updated_at')
        )
        primary = integrations[0]
        others = integrations[1:]

        logger.warning(
            f"Resolving {count} active entries for team_id={team_id}: "
            f"keeping id={primary.id} (business={primary.business_id}), "
            f"deactivating {len(others)} duplicates"
        )

        for integration in others:
            integration.is_active = False
            integration.save(update_fields=['is_active'])
            logger.info(
                f"Deactivated duplicate active SlackIntegration id={integration.id} "
                f"team_id={team_id} business={integration.business_id}"
            )


